  "Bereich wählen": { en: "Choose a section", es: "Elegir una sección", ar: "اختر قسمًا" },
  "Doppelgänger-Paare": { en: "Look-alike pairs", es: "Parejas de parecidos", ar: "أزواج الأشباه" },
  "Giftige Pflanzen": { en: "Poisonous plants", es: "Plantas venenosas", ar: "نباتات سامة" },
  "Pilze": { en: "Mushrooms", es: "Setas", ar: "الفطر" },
  "Suchergebnisse": { en: "Search results", es: "Resultados de la búsqueda", ar: "نتائج البحث" },
  "Kein Treffer. Probiere einen anderen Namen.": { en: "No match. Try a different name.", es: "Sin resultados. Prueba con otro nombre.", ar: "لا توجد نتيجة. جرّب اسمًا آخر." },
  "Essbar und giftig sehen sich oft zum Verwechseln ähnlich. Tippe auf ein Foto für Details.": {
    en: "Edible and poisonous often look so alike that they are easy to mix up. Tap a photo for details.",
    es: "Lo comestible y lo venenoso suelen parecerse hasta confundirse. Toca una foto para ver los detalles.",
    ar: "غالبًا ما يتشابه الصالح للأكل والسام إلى حدّ الخلط بينهما. المس صورة لعرض التفاصيل." },
  "Diese Auswahl ist nicht vollständig. Viele weitere Pflanzen sind giftig, besonders gefährlich sind sie für Kinder.": {
    en: "This selection is not complete. Many more plants are poisonous, and they are especially dangerous for children.",
    es: "Esta selección no es completa. Muchas otras plantas son venenosas, y son especialmente peligrosas para los niños.",
    ar: "هذه القائمة غير كاملة. هناك نباتات سامة كثيرة أخرى، وهي خطرة بشكل خاص على الأطفال." },
  "Giftige Doppelgänger essbarer Pflanzen": { en: "Poisonous look-alikes of edible plants", es: "Parecidos venenosos de plantas comestibles", ar: "أشباه سامة للنباتات الصالحة للأكل" },
  "Weitere giftige Pflanzen": { en: "More poisonous plants", es: "Otras plantas venenosas", ar: "نباتات سامة أخرى" },
